8	DO $$
9	BEGIN
10	  IF NOT EXISTS (
11	    SELECT 1 FROM pg_type
12	    WHERE typname = 'onboarding_persona'
13	      AND typnamespace = 'public'::regnamespace
14	  ) THEN
15	    CREATE TYPE public.onboarding_persona AS ENUM ('solo_artist', 'studio_owner');
16	  END IF;
17	END
18	$$;
19	
20	ALTER TABLE public.profiles
21	  ADD COLUMN IF NOT EXISTS onboarding_persona public.onboarding_persona NOT NULL DEFAULT 'studio_owner';
22	
23	ALTER TABLE public.profiles
24	  ADD COLUMN IF NOT EXISTS onboarded_at timestamptz;
25	
26	CREATE INDEX IF NOT EXISTS idx_profiles_onboarding_persona
27	  ON public.profiles (onboarding_persona);
